// v0.13 (Round 11) MedicationRepository — 抽象接口（domain 层）//// 4 层架构示范：domain 定义"业务能做什么"，data 层提供 Drift 实现。// UI / UseCase 只依赖这个 abstract class，不直接 import Drift。//// 实现方在 `lib/data/repositories/medication_repository_impl.dart`。library;import 'package:chroniccare/domain/entities/hour_minute.dart';import 'package:chroniccare/domain/entities/medication_entity.dart';/// 吃药信息仓库（domain 抽象接口）////// UI / UseCase / tests 全部依赖这个接口，**不直接 import Drift**。abstract class MedicationRepository {  /// 监听所有启用的药物  Stream<List<MedicationEntity>> watchAll();  /// 监听所有药物（含已停药，给"用药报告"用）  ///  /// 历史用药可能在窗口内有打卡记录，但 medication.isActive=false，  /// 报告必须包含这些数据才能完整还原用户服药历史。  Stream<List<MedicationEntity>> watchAllIncludingInactive();  /// 添加药物  Future<int> add({    required String name,    required double dosage,    required String dosageUnit,    required List<HourMinute> times,    DateTime? startDate,    DateTime? refillAt,    int refillReminderDays,    bool isActive,    DateTime? endDate,  });  /// 整体更新（用 entity 接收，impl 内部转 Drift row）  Future<bool> update(MedicationEntity medication);  /// 软停药 / 恢复  Future<bool> setActive({    required int medicationId,    required bool isActive,  });  /// 硬删除  Future<int> delete(int id);  /// 只更新续方相关字段  Future<bool> updateRefill({    required int medicationId,    required DateTime? refillAt,    int? reminderDays,  });}